function XYZToCIELAB(X, Y, Z: Double): TRGBTuple;
var
  f: Double;
  f_inv: Double;
begin
  // D65 Weißpunkt Referenzwerte
  const Xn = 95.047;
  const Yn = 100.000;
  const Zn = 108.883;

