  y_norm := Y / Yn;
  z_norm := Z / Zn;

  // Berechnung von f(t)
  f := 1.055 * y_norm - 0.055;
  f_inv := 1.0 / f;

  // CIELAB Berechnung (L*, a*, b*)
  Result.Item1 := 116.0 * f;          // L*
  Result.Item2 := 116.0 * (f_inv * x_norm - (f_inv * x_norm - 1.0) * y_norm * f_inv); // a* (vereinfacht, genaue CIELAB-Formeln sind komplexer)
  Result.Item3 := 116.0 * (f_inv * y_norm - (f_inv * x_norm - 1.0) * y_norm * f_inv); // b* (vereinfacht, genaue CIELAB-Formeln sind komplexer)
end;


// Berechnet die Farbabweichung Delta E 2000 zwischen zwei Farben
function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
var
  R1_lin, G1_lin, B1_lin: Double;
  R2_lin, G2_lin, B2_lin: Double;
  X1, Y1, Z1, X2, Y2, Z2: Double;
