  // Funktion f(t) = (t/t_ref)^(1/3) falls t > Epsilon, sonst t/(3*t_ref^2)
  // Korrektur der Syntaxfehler: 'if ... then ... else ...' muss korrekt abgeschlossen sein.
  if X > Epsilon then
    fx := Power(X / Xn, 1.0/3.0)
  else
    fx := X / (3.0 * Xn * Xn);

  if Y > Epsilon then
    fy := Power(Y / Yn, 1.0/3.0)
  else
    fy := Y / (3.0 * Yn * Yn);

