  // b* = 200 * (f(Y/Yn) - f(Z/Zn))

  Result.X := 116.0 * fy - 16.0; // L*
  Result.Y := 500.0 * (fx - fy);  // a*
  Result.Z := 200.0 * (fy - fz);  // b*
