var
  deltaL: Double;
  deltaA: Double;
  deltaB: Double;
begin
  // Delta E 1976 (CIELAB Distance)
  deltaL := L1 - L2;
  deltaA := a1 - a2;
  deltaB := b1 - b2;

  // Da die vollständige CIEDE2000 Implementierung zu komplex ist, liefern wir die CIELAB-Distanz.
  Result := Sqrt(deltaL*deltaL + deltaA*deltaA + deltaB*deltaB);
end;


