function ScaleRGBToXYZ(R, G, B: Byte): Double;
var
  R_linear, G_linear, B_linear: Double;
  X_factor: Double;
begin
  // sRGB-zu-Linearisierung
  R_linear := (R / 255.0);
  G_linear := (G / 255.0);
  B_linear := (B / 255.0);

  // sRGB Gamma-Kurven-Umkehrung
  R_linear := If(R_linear <= 0.04045, R_linear / 12.92, Power(R_linear, 1.0 / 2.4));
  G_linear := If(G_linear <= 0.04045, G_linear / 12.92, Power(G_linear, 1.0 / 2.4));
  B_linear := If(B_linear <= 0.04045, B_linear / 12.92, Power(B_linear, 1.0 / 2.4));

  // XYZ-Konversion (X-Komponente bei D65)
  X_factor := 0.95047; 

  Result := R_linear * X_factor; 
end;

// --- Hilfsfunktion 2: XYZ zu CIELAB (L*, a*, b*) ---
function XYZToCIELAB(X, Y, Z: Double): TTuple<Double, Double, Double>;
var
  fX, fY, fZ: Double;
  f_C, f_H, f_L: Double;
  f_transform: function(c: Double): Double;
begin
  // D65-Weißpunkt-Werte (Referenzwerte für XYZ)
  const Xn = 95.047;
  const Yn = 100.000;
  const Zn = 108.883;

  // Funktion für die Nicht-lineare Transformation (Gamma-Funktion)
  f_transform := function(c: Double): Double;
  begin
    if c > (6.0 / 29.0) then
      Power(c, 1.0 / 3.0)
    else
      (c / 3.0) + (29.0 / 3.0) * Power(c, 2.0 / 3.0);
  end;

  fX := X / Xn;
  fY := Y / Yn;
  fZ := Z / Zn;

  fC := f_transform(fY);
  fH := f_transform(fX);
  fL := f_transform(fZ);

