function RGBToXYZ(R, G, B: Byte): record
var
  R_f, G_f, B_f: Single;
  X, Y, Z: Single;
begin
  // Normalisieren (0-1)
  R_f := R / 255.0;
  G_f := G / 255.0;
  B_f := B / 255.0;

  // sRGB Gamma Korrektur (für D65)
  var R_linear, G_linear, B_linear: Single;
  R_linear := (R_f > 0.04045) ? ((R_f + 0.055) / 1.055) ^ (1.0 / 2.4) : R_f / 12.92;
  G_linear := (G_f > 0.04045) ? ((G_f + 0.055) / 1.055) ^ (1.0 / 2.4) : G_f / 12.92;
  B_linear := (B_f > 0.04045) ? ((B_f + 0.055) / 1.055) ^ (1.0 / 2.4) : B_f / 12.92;

  // XYZ berechnen (D65)
  X := R_linear * X_MATRIX.X + G_linear * X_MATRIX.Y + B_linear * X_MATRIX.Z;
  Y := R_linear * X_MATRIX.X + G_linear * X_MATRIX.Y + B_linear * X_MATRIX.Z; // Wichtig: Matrix ist für R, G, B angewendet
  Z := R_linear * X_MATRIX.X + G_linear * X_MATRIX.Y + B_linear * X_MATRIX.Z;

  // Korrekte XYZ Berechnung basierend auf Standard-sRGB Matrix
  X := (R_linear * 0.4124564 + G_linear * 0.3575761 + B_linear * 0.1804375) * 100.0;
  Y := (R_linear * 0.2126729 + G_linear * 0.7151522 + B_linear * 0.0193339) * 100.0;
  Z := (R_linear * 0.0193339 + G_linear * 0.0193339 + B_linear * 0.9504951) * 100.0;

  Result := record
    X, Y, Z: Single;
end;

// Funktion zur Umrechnung von XYZ nach CIELAB
function XYZToLab(X, Y, Z: Single): record
var
  f: Single;
  Xn, Yn, Zn: Single;
begin
  // Normalisierung (X/Xn, Y/Yn, Z/Zn)
  f := (X / Xn) / (Y / Yn) / (Z / Zn);

  // CIELAB Berechnung
  var L: Single;
  var a: Single;
  var b: Single;
begin
  L := 116.0 * f - 16.0;
  a := 116.0 * (f - Yn) / (Yn - Zn);
  b := 116.0 * (f - Xn) / (Xn - Zn);

  Result := record
    L, a, b: Single;
end;

// Funktion zur Berechnung des Delta E 2000
function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
