uses
  SysUtils, Math;

// --- Konstanten und Hilfsfunktionen für die Farbkonvertierung ---

// 1. XYZ-Matrix für sRGB (D65-Weißpunkt)
const
  // Koeffizienten für die lineare Transformation von sRGB zu XYZ (D65)
  X_COEFF_R = 0.4124564;
  X_COEFF_G = 0.3575761;
  X_COEFF_B = 0.1804375;

  Y_COEFF_R = 0.2126729;
  Y_COEFF_G = 0.7151522;
  Y_COEFF_B = 0.0193339;

  Z_COEFF_R = 0.0193339;
  Z_COEFF_G = 0.0193339;
  Z_COEFF_B = 0.9504951;

// 2. Weißpunkt D65 (Xn, Yn, Zn) - Normalisierte Werte (0-1)
const
  Xn = 0.95047;
  Yn = 1.00000;
  Zn = 1.08883;

// 3. CIELAB und CIEDE2000 Konstanten
const
  K_L = 1.0;
  K_C = 1.0;
  K_H = 1.0;

// Funktion zur Umrechnung von RGB (0-255) nach XYZ
function RGBToXYZ(R, G, B: Byte): record
begin
  // Normalisieren (0-1)
  R_f := R / 255.0;
  G_f := G / 255.0;
  B_f := B / 255.0;

  // sRGB Gamma Korrektur (Linearization)
  R_linear := (R_f > 0.04045)
    ? ((R_f + 0.055) / 1.055) ^ (1.0 / 2.4)
    : R_f / 12.92;
  G_linear := (G_f > 0.04045)
    ? ((G_f + 0.055) / 1.055) ^ (1.0 / 2.4)
    : G_f / 12.92;
  B_linear := (B_f > 0.04045)
    ? ((B_f + 0.055) / 1.055) ^ (1.0 / 2.4)
    : B_f / 12.92;

  // XYZ berechnen (D65)
  X := R_linear * X_COEFF_R + G_linear * X_COEFF_G + B_linear * X_COEFF_B;
  Y := R_linear * Y_COEFF_R + G_linear * Y_COEFF_G + B_linear * Y_COEFF_B;
  Z := R_linear * Z_COEFF_R + G_linear * Z_COEFF_G + B_linear * Z_COEFF_B;

  Result := record
    X, Y, Z: Single;
end;

// Funktion zur Umrechnung von XYZ nach CIELAB
function XYZToLab(X, Y, Z: Single): record
begin
  // Normalisierung (X/Xn, Y/Yn, Z/Zn)
  f := (X / Xn) / (Y / Yn) / (Z / Zn);

  // CIELAB Berechnung
  L := 116.0 * f - 16.0;
  a := 116.0 * (f - Yn) / (Yn - Zn);
  b := 116.0 * (f - Xn) / (Xn - Zn);

  Result := record
    L, a, b: Single;
end;

// Funktion zur Berechnung des Delta E 2000
function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
var
  Lab1, Lab2: record;
  L1, a1, b1, L2, a2, b2: Single;
  DeltaL, Deltaa, Deltab: Single;
  Numerator: Single;
  Denominator: Single;
  SumSq1, SumSq2, TotalSumSq: Single;
  DeltaE2000_val: Double;
begin
  // 1. RGB zu XYZ konvertieren
  Lab1 := RGBToXYZ(R1, G1, B1);
  Lab2 := RGBToXYZ(R2, G2, B2);

  // 2. XYZ zu CIELAB konvertieren
  L1, a1, b1 := XYZToLab(Lab1.X, Lab1.Y, Lab1.Z);
  L2, a2, b2 := XYZToLab(Lab2.X, Lab2.Y, Lab2.Z);

  // 3. Delta L*a*b* Berechnung
  DeltaL := L1 - L2;
  Deltaa := a1 - a2;
  Deltab := b1 - b2;

  // 4. CIEDE2000 Formel (kL=kC=kH=1)
  SumSq1 := L1*L1 + a1*a1 + b1*b1;
  SumSq2 := L2*L2 + a2*a2 + b2*b2;
  TotalSumSq := SumSq1 + SumSq2;

  Numerator := (DeltaL * DeltaL) + (Deltaa * Deltaa) + (Deltab * Deltab);
  Denominator := 3.0 * TotalSumSq;

  if Denominator > 0.0 then
    DeltaE2000_val := Sqrt(Numerator / Denominator)
  else
    DeltaE2000_val := 0.0;

  Result := DeltaE2000_val;
end;
```

Der bereitgestellte Delphi-Code enthält mehrere Fehler und Stilprobleme. Hier ist eine detaillierte Analyse der Fehler in beiden Funktionen:

