unit ColorUtils;

interface

uses
  System.SysUtils, System.Math;

type
  TColorConverter = record
    function RGBToXYZ(R, G, B: Byte): array[1..3] of Double;
    function XYZToLab(X, Y, Z: Double): array[1..3] of Double;
    function CIEDE2000(L1, a1, b1, L2, a2, b2: Double): Double;
    function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
  end;

implementation

// Konstanten für D65 Weißpunkt
const
  Xn = 0.95047;
  Yn = 1.00000;
  Zn = 1.08883;

// Funktion zur Umrechnung von sRGB zu XYZ (D65)
function TColorConverter.RGBToXYZ(R, G, B: Byte): array[1..3] of Double;
var
  R_lin, G_lin, B_lin: Double;
  X, Y, Z: Double;
begin
  // sRGB zu linearem RGB
  R_lin := (R / 255.0) * (if (R / 255.0) <= 0.04045 then 12.92 * (R / 255.0) else 1.055 * Power((R / 255.0) + 0.055, 2.4));
  G_lin := (G / 255.0) * (if (G / 255.0) <= 0.04045 then 12.92 * (G / 255.0) else 1.055 * Power((G / 255.0) + 0.055, 2.4));
  B_lin := (B / 255.0) * (if (B / 255.0) <= 0.04045 then 12.92 * (B / 255.0) else 1.055 * Power((B / 255.0) + 0.055, 2.4));

  // RGB zu XYZ (D65)
  // Formeln basieren auf der IEC 61966-2-1 Norm für D65
  X := 0.4124564 * R_lin + 0.3575761 * G_lin + 0.1804375 * B_lin;
  Y := 0.2126729 * R_lin + 0.7151522 * G_lin + 0.0721750 * B_lin;
  Z := 0.0193339 * R_lin + 0.1191920 * G_lin + 0.9503041 * B_lin;

  Result[1] := X;
  Result[2] := Y;
  Result[3] := Z;
end;

// Hilfsfunktion zur Anwendung der XYZ-zu-CIE L*a*b* Transformation
function f_xyz_to_lab(T_xyz: array[1..3] of Double): array[1..3] of Double;
var
  Xt, Yt, Zt: Double;
  ft: Double;
  f_result: Double;
begin
  Xt := T_xyz[1];
  Yt := T_xyz[2];
  Zt := T_xyz[3];

  // Kappa (Trilinear interpolation factor based on reference white point)
  // Da wir D65 verwenden, ist die Konvertierung in LAB direkt möglich.

  // Funktion f(t) = t^(1/3) wenn t > 0.008856, sonst t / 24389
  procedure f(t: Double): Double;
  begin
    if t > 0.008856 then
      f_result := Power(t, 1.0/3.0)
    else
      f_result := (t / 24389.0) + 16.0/24389.0; // Equivalent to t/24389 + 0.000651
  end;

  // L* = 116 * f(Y/Yn) - 16
  f(Yt / Yn);
  var L: Double := 116.0 * f_result - 16.0;

  // a* = 500 * (f(X/Xn) - f(Y/Yn))
  f(Xt / Xn);
  var a: Double := 500.0 * (f_result - f_result); // Note: Y/Yn function is reused, f_result holds f(X/Xn) now
  // Recompute f(Y/Yn) for 'a' calculation, as f_result was overwritten by f(X/Xn)
  f(Yt / Yn);
  a := 500.0 * (f_result - f_result); // This is still wrong due to state overwriting. Let's separate.

  // --- Recalculation for clarity ---

  // f(t) function wrapper
  procedure F(t: Double): Double;
  begin
    if t > 0.008856 then
      F := Power(t, 1.0/3.0)
    else
      F := (t / 24389.0) + 16.0/24389.0;
  end;

  var fX, fY, fZ: Double;
  fX := F(Xt / Xn);
  fY := F(Yt / Yn);
  fZ := F(Zt / Zn);

  var L_val: Double := 116.0 * fY - 16.0;
  var a_val: Double := 500.0 * (fX - fY);
  var b_val: Double := 500.0 * (fZ - fY);

  Result[1] := L_val;
  Result[2] := a_val;
  Result[3] := b_val;
end;


// CIEDE2000 Berechnung
function TColorConverter.CIEDE2000(L1, a1, b1, L2, a2, b2: Double): Double;
var
  deltaL, deltaA, deltaB: Double;
  L_bar: Double;
  C1: Double;
  C2: Double;
  C_bar: Double;
  h1, h2: Double;
  DeltaC: Double;
  DeltaH: Double;
  kL, kC, kH: Double;
  G: Double;
