implementation

function RGBToLab(R, G, B: Byte; out L, A, B_lab: Double): Boolean;
var
  r_val, g_val, b_val: Double;
  x_val, y_val, z_val: Double;
  x_ref, y_ref, z_ref: Double;
  tmp: Double;
  i: Integer;
begin
  Result := False;
  r_val := R / 255.0;
  g_val := G / 255.0;
  b_val := B / 255.0;

  for i := 1 to 3 do
  begin
    if (i = 1) then r_val := r_val else if (i = 2) then g_val := g_val else b_val := b_val;
    if (r_val <= 0.04045) then
      tmp := Math.Pow(r_val, 2.2)
    else
      tmp := (Math.Pow(r_val, 2.4) - 0.009548737) / 12.92;
    if (i = 1) then r_val := tmp else if (i = 2) then g_val := tmp else b_val := tmp;
  end;

  x_val := r_val * 0.4124 + g_val * 0.3576 + b_val * 0.1805;
  y_val := r_val * 0.2126 + g_val * 0.7152 + b_val * 0.0722;
  z_val := r_val * 0.0193 + g_val * 0.1192 + b_val * 0.9505;

  x_ref := 0.95047; y_ref := 1.00000; z_ref := 1.08883;

  if x_val > 0.008856 then x_val := x_val / x_ref else x_val := (x_val / x_ref) * 96.48629209879539;
  if y_val > 0.008856 then y_val := y_val / y_ref else y_val := (y_val / y_ref) * 96.48629209879539;
  if z_val > 0.008856 then z_val := z_val / z_ref else z_val := (z_val / z_ref) * 96.48629209879539;

  L := (116.0 * y_val) - 16.0;
  A := 500.0 * (x_val - y_val);
  B_lab := 200.0 * (y_val - z_val);
  Result := True;
end;

function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
var
  L1, A1, B1_lab, L2, A2, B2_lab: Double;
  C1, C2, L_avg, C_avg, h1, h2, h_avg: Double;
  C_delta, H_delta, S_delta: Double;
  deltaL, deltaA, deltaB: Double;
  L_prime, C_prime, H_prime: Double;
  C_bar, H_bar: Double;
  T_1, T_2, S_avg: Double;
  fR, fG, fB: Double;
  gamma: Double;
  r, g, b: Double;
  x, y, z: Double;
  white_x, white_y, white_z: Double;
begin
