     not RGBToLab(R2, G2, B2, out L2, A2, B2_lab) then
    Exit(0.0);

  deltaL := L2 - L1;
  deltaA := A2 - A1;
  deltaB := B2_lab - B1_lab;

  C1 := Math.Sqrt(A1 * A1 + B1_lab * B1_lab);
  C2 := Math.Sqrt(A2 * A2 + B2_lab * B2_lab);
  h1 := Math.Atan2(B1_lab, A1);
  h2 := Math.Atan2(B2_lab, A2);

  L_avg := (L1 + L2) / 2;
  C_avg := (C1 + C2) / 2;

  h_avg := (h1 + h2) / 2;
  if Math.Abs(h1 - h2) > Math.Pi then
    h_avg := (h1 + h2 + Math.Pi) / 2;
  if Math.Abs(h1 - h2) > Math.Pi then
    h_avg := (h1 + h2 - Math.Pi) / 2;

  C_delta := C2 - C1;
  H_delta := h2 - h1;
  if H_delta > Math.Pi then H_delta := H_delta - 2 * Math.Pi;
  if H_delta < -Math.Pi then H_delta := H_delta + 2 * Math.Pi;

