// --- RGB ⇢ linear RGB -----------------------------------------------
procedure LinearizeRGB(const R,G,B: Byte; out Rl,Gl,Bl: Double);
var
  r,g,b: Double;
begin
  r := R / 255.0;
  g := G / 255.0;
  b := B / 255.0;
  if r <= 0.04045 then r := r / 12.92
  else                 r := Power((r + 0.055)/1.055, 2.4);
  if g <= 0.04045 then g := g / 12.92
  else                 g := Power((g + 0.055)/1.055, 2.4);
  if b <= 0.04045 then b := b / 12.92
  else                 b := Power((b + 0.055)/1.055, 2.4);
  Rl := r; Gl := g; Bl := b;
end;

// --- Linear RGB ⇢ XYZ (sRGB, D65) -------------------------------------
procedure RGBToXYZ(const R,G,B: Byte; out X,Y,Z: Double);
var
  Rl,Gl,Bl: Double;
begin
  LinearizeRGB(R,G,B,Rl,Gl,Bl);
  // Matrix for sRGB → XYZ (D65 reference white)
  X := (0.4124 * Rl + 0.3576 * Gl + 0.1805 * Bl) * 100.0;
  Y := (0.2126 * Rl + 0.7152 * Gl + 0.0722 * Bl) * 100.0;
  Z := (0.0193 * Rl + 0.1192 * Gl + 0.9505 * Bl) * 100.0;
end;

// --- XYZ ⇢ Lab -------------------------------------------------------
procedure XYZToLab(const X,Y,Z: Double; out L,a,b: Double);
const
  Xn = 95.047;  // D65 reference white
  Yn = 100.000;
  Zn = 108.883;
  Epsilon = 0.008856;  // 216/24389
  Kappa   = 903.3;      // 24389/27
  function f(t: Double): Double;
  begin
    if t > Epsilon then
      Result := Power(t, 1/3)
    else
      Result := (Kappa * t + 16.0) / 116.0;
  end;
var
  fx,fy,fz: Double;
begin
  fx := f(X / Xn);
  fy := f(Y / Yn);
  fz := f(Z / Zn);
  L := 116.0 * fy - 16.0;
  a := 500.0 * (fx - fy);
  b := 200.0 * (fy - fz);
end;

// --- Lab ⇢ ΔE00 -------------------------------------------------------
function DeltaE2000Lab(
  const L1,a1,b1,L2,a2,b2: Double): Double;
const
  DegToRad = Pi / 180.0;
  RadToDeg = 180.0 / Pi;
var
  // helper variables
  C1,C2,meanC,G,ap1,ap2,C1p,C2p,h1p,h2p;
  ΔLp,ΔCp,ΔHp,meanL,meanHp;
  hSum,deltaHue,meanHue;
  T,S_L,S_C,S_H,R_C,R_T;
  // intermediate
  powC1p, powC2p, powCbarP;
  sinΔHue: Double;
  cosHP, cos2HP, cos3HP, cos4HP: Double;
begin
  // Chromas
  C1 := Sqrt(a1*a1 + b1*b1);
  C2 := Sqrt(a2*a2 + b2*b2);
  meanC := (C1 + C2) / 2.0;
  // Compensation for nonlinearity
  G := 0.5 * (1 - Sqrt(Power(meanC, 7) / (Power(meanC, 7) + Power(25.0, 7))));
  // Adjusted a*-coordinates
  ap1 := (1 + G) * a1;
  ap2 := (1 + G) * a2;
  // Adjusted chromas
  C1p := Sqrt(ap1*ap1 + b1*b1);
  C2p := Sqrt(ap2*ap2 + b2*b2);
  // Adjusted hue angles
  h1p := ArcTan2(b1, ap1);
  if h1p < 0 then h1p := h1p + 2*Pi;
  h2p := ArcTan2(b2, ap2);
  if h2p < 0 then h2p := h2p + 2*Pi;
  // Differences
  ΔLp := L2 - L1;
  ΔCp := C2p - C1p;
  deltaHue := h2p - h1p;
  if Abs(deltaHue) > Pi then
    if deltaHue > 0 then
      deltaHue := deltaHue - 2*Pi
    else
      deltaHue := deltaHue + 2*Pi;
  ΔHp := 2 * Sqrt(C1p*C2p) * Sin(deltaHue / 2.0);
  // Means
  meanL := (L1 + L2) / 2.0;
  meanC := (C1p + C2p) / 2.0;
  hSum := h1p + h2p;
  if Abs(h1p - h2p) > Pi then
    if hSum < 2*Pi then
      hSum := hSum + 2*Pi
    else
      hSum := hSum - 2*Pi;
  if (C1p * C2p) = 0 then
    meanHue := hSum
  else if Abs(h1p - h2p) <= Pi then
    meanHue := hSum / 2.0
  else
    if hSum < 2*Pi then
      meanHue := (hSum + 2*Pi) / 2.0
    else
      meanHue := (hSum - 2*Pi) / 2.0;
  // Compute T
  cosHP   := Cos(meanHue - Pi/6);
  cos2HP  := Cos(2 * meanHue);
  cos3HP  := Cos(3 * meanHue + Pi/30);
  cos4HP  := Cos(4 * meanHue - 63 * Pi / 100);
  T := 1
     - 0.17 * cosHP
     + 0.24 * cos2HP
     + 0.32 * cos3HP
     - 0.20 * cos4HP;
  // Scale factors
  S_L := 1 + ((0.015 * Power((meanL - 50), 2)) / Sqrt(20 + Power((meanL - 50), 2)));
  S_C := 1 + 0.045 * meanC;
  S_H := 1 + 0.015 * meanC * T;
  // Rotation term
  // deltaTheta in degrees
  deltaHue := 30 * Exp(-(Power((meanHue*RadToDeg - 275) / 25.0, 2)));
  // C_bar^7 term
  powCbarP := Power(meanC, 7);
  R_C := 2 * Sqrt(powCbarP / (powCbarP + Power(25.0, 7)));
  R_T := - Sin(2 * deltaHue * DegToRad) * R_C;
  // Final DeltaE
  Result := Sqrt(
    Sqr(ΔLp / S_L) +
    Sqr(ΔCp / S_C) +
    Sqr(ΔHp / S_H) +
    R_T * (ΔCp / S_C) * (ΔHp / S_H)
  );
end;

// --- Public interface --------------------------------------------------
