  meanCPrime, meanhPrime: Double;
  // Chromaticity adjustments
  C1, C2, G: Double;
  // Adjusted a components
  a1Prime, a2Prime: Double;
  // Hue angles
  h1Prime, h2Prime: Double;
  // Weight functions
  SL, SC, SH, T, RC, RT: Double;
  deltaThetaDeg: Double;
