  // 3. a' components
  a1Prime := (1.0 + G) * a1;
  a2Prime := (1.0 + G) * a2;
  C1Prime := Sqrt(a1Prime * a1Prime + b1 * b1);
  C2Prime := Sqrt(a2Prime * a2Prime + b2 * b2);

