const
  D65_Xn = 0.95047;
  D65_Yn = 1.0;
  D65_Zn = 1.08883;

  /////////////////////////////////
  // Helper: sRGB linearization
  /////////////////////////////////
  function LinearizeSRGB(x: Double): Double;
  begin
    if x <= 0.04045 then
      Result := x / 12.92
    else
      Result := Power((x + 0.055) / 1.055, 2.4);
  end;

