  /////////////////////////////////
  function RGBtoLab(R, G, B: Byte): TLab;
  var
    r, g, b: Double;
    // sRGB to XYZ (D65)
    X, Y, Z: Double;
    // XYZ to Lab
    fx, fy, fz: Double;
  begin
    // Normalize to [0,1] and linearize
    r := LinearizeSRGB(R / 255.0);
    g := LinearizeSRGB(G / 255.0);
    b := LinearizeSRGB(B / 255.0);

    // sRGB D65 to XYZ
    X := 0.4124564 * r + 0.3575761 * g + 0.1804375 * b;
    Y := 0.2126729 * r + 0.7151522 * g + 0.0721750 * b;
    Z := 0.0193339 * r + 0.1191920 * g + 0.9503041 * b;

