    // 3. h' angles
    h1Prime, h2Prime: Double;
    hPrimeDiff: Double;
    HPrimeMean: Double;
    // 4. Delta L', Delta C', Delta H'
    deltaLPrime, deltaCPrime, deltaHPrime: Double;
    // 5. SL, SC, SH
    SL, SC, SH: Double;
    // 6. Rotation term RT
    RT: Double;
    // 7. Final DeltaE
    DeltaE: Double;
  begin
    // ---- Step 1: Chromaticity values ----
    // Mean L'
    LPrimeMean := (Lab1.L + Lab2.L) / 2.0;

    // Compute C'
    a1PrimeSq := Square(Lab1.a);
    a2PrimeSq := Square(Lab2.a);
    C1Prime := Sqrt(a1PrimeSq + Square(Lab1.b));
    C2Prime := Sqrt(a2PrimeSq + Square(Lab2.b));

    // Mean C' (in formulas, sometimes called C_prime mean)
    // note it is used below
    // ---- Step 2: Compute a' ----
    // Compute G
    var G    : Double;
    var C1Sq : Double;
    var C2Sq : Double;
    G      := 0.5 * (1 - Sqrt(Power((C1Prime + C2Prime)/2.0, 7) / (Power((C1Prime + C2Prime)/2.0, 7) + 6103515625)));
    a1Prime := (1 + G) * Lab1.a;
    a2Prime := (1 + G) * Lab2.a;

    C1Prime := Sqrt(Square(a1Prime) + Square(Lab1.b));
    C2Prime := Sqrt(Square(a2Prime) + Square(Lab2.b));

    // ---- Step 3: Compute h' ----
    h1Prime := HueAngle(a1Prime, Lab1.b);
    h2Prime := HueAngle(a2Prime, Lab2.b);

    // ---- Step 4: Delta L', Delta C', Delta H' ----
    deltaLPrime := Lab2.L - Lab1.L;
    deltaCPrime := C2Prime - C1Prime;

    // Avoid unrealistic values for deltaHPrime when C1Prime*C2Prime = 0
    if (C1Prime * C2Prime = 0) then
      deltaHPrime := 0
    else
    begin
      // If difference in hue angles > 180°, adjust
      var hDiff := h2Prime - h1Prime;
      if Abs(hDiff) > 180 then
        if hDiff > 0 then
          hDiff := hDiff - 360
        else
          hDiff := hDiff + 360;
      deltaHPrime := 2 * Sqrt(C1Prime * C2Prime) * Sin(DegToRad(hDiff / 2.0));
    end;

    // ---- Step 5: Compute SL, SC, SH ----
    SL := 1 + 0.015 * Power(LPrimeMean - 50, 2) / Sqrt(20 + Power(LPrimeMean - 50, 2));
    SC := 1 + 0.045 * CPrimeMean;
    // -- Compute mean hue for T
    var hPrimeMeanTmp: Double;
    if (C1Prime * C2Prime = 0) then
      hPrimeMeanTmp := h1Prime + h2Prime
    else
    begin
      if Abs(h1Prime - h2Prime) <= 180 then
        hPrimeMeanTmp := (h1Prime + h2Prime) / 2.0
      else
        if h1Prime + h2Prime < 360 then
          hPrimeMeanTmp := (h1Prime + h2Prime + 360) / 2.0
        else
          hPrimeMeanTmp := (h1Prime + h2Prime - 360) / 2.0;
    end;

    var T: Double;
    T := 1 - 0.17 * Cos(DegToRad(hPrimeMeanTmp - 30))
        + 0.24 * Cos(DegToRad(2 * hPrimeMeanTmp))
        + 0.32 * Cos(DegToRad(3 * hPrimeMeanTmp + 6))
        - 0.20 * Cos(DegToRad(4 * hPrimeMeanTmp - 63));

    SH := 1 + 0.015 * CPrimeMean * T;

    // ---- Step 6: Rotation Term R_T ----
    var deltaTheta: Double := 30 * Exp(-Power((hPrimeMeanTmp - 275) / 25.0, 2));
    RT := -2 * Sin(DegToRad(2 * deltaTheta)) * T;

    // ---- Step 7: Final DeltaE ----
    DeltaE := Sqrt(Power(deltaLPrime / SL, 2) +
                   Power(deltaCPrime / SC, 2) +
                   Power(deltaHPrime / SH, 2));
    Result := DeltaE;
  end;

  /////////////////////////////////
  // Main function
  /////////////////////////////////
function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
var
  Lab1, Lab2: TLab;
begin
  Lab1 := RGBtoLab(R1, G1, B1);
  Lab2 := RGBtoLab(R2, G2, B2);
