    r := Byte(R) / 255.0;
    g := Byte(G) / 255.0;
    b := Byte(B) / 255.0;

    if r > 0.04045 then r := Power((r + 0.055) / 1.055, 2.4) else r := r / 12.92;
    if g > 0.04045 then g := Power((g + 0.055) / 1.055, 2.4) else g := g / 12.92;
    if b > 0.04045 then b := Power((b + 0.055) / 1.055, 2.4) else b := b / 12.92;

