    if fy > 0.008856 then fy := Power(fy, 1/3) else fy := (7.787 * fy) + (16/116);
    if fz > 0.008856 then fz := Power(fz, 1/3) else fz := (7.787 * fz) + (16/116);

    Result.L := (116 * fy) - 16;
    Result.A := 500 * (fx - fy);
    Result.B := 200 * (fy - fz);
  end;

begin
