  dH_prime := ArcTan2(lab2.B, lab2.A) - ArcTan2(lab1.B, lab1.A);
  // Adjust for wrap-around
  if dH_prime > Pi then dH_prime := dH_prime - 2.0 * Pi
  else if dH_prime < -Pi then dH_prime := dH_prime + 2.0 * Pi;

  // Because Delta E 2000 uses a specific Delta H calculation:
  // Instead of raw DH, we use the component Delta H' based on Lab values
  // to avoid trigonometric singularities near origin.
  // A more robust way for Delta H':
  // deltaH_prime = sqrt( (deltaE_76^2) - (deltaL^2) - (deltaC^2) ) 
  // But the standard uses the trigonometric difference of hues.

