  dLp, dCp: Double;
  Lbar, Cbar2, hbar: Double;
  T, dTheta, RC, SL, SC, SH, RT: Double;
  Cbar7, Cbar2_7: Double;
  sq: Double;
begin
  // Step 1: chromaticities
  C1   := Sqrt(Lab1.A * Lab1.A + Lab1.B * Lab1.B);
  C2   := Sqrt(Lab2.A * Lab2.A + Lab2.B * Lab2.B);
  Cbar := (C1 + C2) / 2.0;

  // Step 2: weighting factor G and adjusted a'
  Cbar7 := Power(Cbar, 7.0);
  G := 0.5 * (1.0 - Sqrt(Cbar7 / (Cbar7 + Power(25.0, 7.0))));

  a1p := Lab1.A * (1.0 + G);
  a2p := Lab2.A * (1.0 + G);
  C1p := Sqrt(a1p * a1p + Lab1.B * Lab1.B);
  C2p := Sqrt(a2p * a2p + Lab2.B * Lab2.B);

  // Step 3: hue angles in degrees [0, 360)
  h1p := ArcTan2(Lab1.B, a1p) * 180.0 / Pi;
  if h1p < 0.0 then
    h1p := h1p + 360.0;
  h2p := ArcTan2(Lab2.B, a2p) * 180.0 / Pi;
  if h2p < 0.0 then
    h2p := h2p + 360.0;

  // Step 4: lightness, chroma, hue differences
  dLp := Lab2.L - Lab1.L;
  dCp := C2p - C1p;

  if C1p * C2p = 0.0 then
    dhp := 0.0
  else
  begin
    dhp := h2p - h1p;
    if dhp > 180.0 then
      dhp := dhp - 360.0;
    if dhp < -180.0 then
      dhp := dhp + 360.0;
  end;

  dHp := 2.0 * Sqrt(C1p * C2p) * Sin(dhp * Pi / 360.0);

  // Step 5: mean values
  Lbar  := (Lab1.L + Lab2.L) / 2.0;
  Cbar2 := (C1p + C2p) / 2.0;

  if C1p * C2p = 0.0 then
    hbar := h1p + h2p
  else
  begin
    if Abs(h1p - h2p) > 180.0 then
      hbar := (h1p + h2p + 360.0) / 2.0
    else
      hbar := (h1p + h2p) / 2.0;
  end;

  // Step 6: T
  T := 1.0
     - 0.17 * Cos(2.0 * hbar * Pi / 180.0)
     + 0.24 * Cos(4.0 * hbar * Pi / 180.0)
     + 0.32 * Cos(6.0 * hbar * Pi / 180.0)
     - 0.08 * Cos(8.0 * hbar * Pi / 180.0);

