  dTheta := 30.0 * Exp(-((hbar - 275.0) / 25.0) * ((hbar - 275.0) / 25.0));
  Cbar2_7 := Power(Cbar2, 7.0);
  RC := 2.0 * Sqrt(Cbar2_7 / (Cbar2_7 + Power(25.0, 7.0)));

