  SL := 1.0 + 0.015 * (Lbar - 50.0) * (Lbar - 50.0) /
        Sqrt(0.045 * (Lbar - 50.0) * (Lbar - 50.0) + 4.0);
  SC := 1.0 + 0.045 * Cbar2;
  SH := 1.0 + 0.015 * Cbar2 * T;

  // Step 9: rotation term RT
  RT := -RC * Sin(2.0 * dTheta * Pi / 180.0);

  // Step 10: CIEDE2000
  sq := (dLp / SL) * (dLp / SL)
       + (dCp / SC) * (dCp / SC)
       + (dHp / SH) * (dHp / SH)
       + RT * (dCp / SC) * (dHp / SH);

  if sq < 0.0 then
    sq := 0.0;  // safeguard against tiny negative from rounding
  Result := Sqrt(sq);
end;

function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
var
  X1, Y1, Z1, X2, Y2, Z2: Double;
  Lab1, Lab2: TLabColor;
