  rL := SRGBToLinear(R);
  gL := SRGBToLinear(G);
  bL := SRGBToLinear(B);

  X := 0.4124564 * rL + 0.3575761 * gL + 0.1804375 * bL;
  Y := 0.2126729 * rL + 0.7373822 * gL + 0.0701850 * bL;
  Z := 0.0193339 * rL + 0.1191920 * gL + 0.9503041 * bL;

  fx := CIELabF(X / Xn);
  fy := CIELabF(Y / Yn);
  fz := CIELabF(Z / Zn);

  L    := 116.0 * fy - 16.0;
  A    := 500.0 * (fx - fy);
  Bval := 200.0 * (fy - fz);
