interface

function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;

implementation

uses
  SysUtils,
  Math;

function SRGBtoLinear(C: Double): Double;
begin
  if C <= 0.04045 then
    Result := C / 12.92
  else
    Result := Power((C + 0.055) / 1.055, 2.4);
end;

procedure RGBtoLab(R, G, B: Byte; out L, A, BB: Double);
const
  Xn = 0.95047;
  Yn = 1.00000;
  Zn = 1.08883;
  E  = 216.0 / 24389.0;
  K  = 841.0 / 108.0;
var
  RL, GL, BL: Double;
  X, Y, Z: Double;
  fx, fy, fz: Double;
begin
  RL := SRGBtoLinear(R / 255.0);
  GL := SRGBtoLinear(G / 255.0);
  BL := SRGBtoLinear(B / 255.0);

  X :=  0.4124564 * RL + 0.3575761 * GL + 0.1804375 * BL;
  Y :=  0.2126729 * RL + 0.7373822 * GL + 0.0701850 * BL;
  Z :=  0.0193339 * RL + 0.1191920 * GL + 0.9503041 * BL;

  X := X / Xn;
  Y := Y / Yn;
  Z := Z / Zn;

  if X > E then
    fx := Power(X, 1.0 / 3.0)
  else
    fx := K * X + 4.0 / 29.0;

  if Y > E then
    fy := Power(Y, 1.0 / 3.0)
  else
    fy := K * Y + 4.0 / 29.0;

  if Z > E then
    fz := Power(Z, 1.0 / 3.0)
  else
    fz := K * Z + 4.0 / 29.0;

  L  := 116.0 * fy - 16.0;
  A  := 500.0 * (fx - fy);
  BB := 200.0 * (fy - fz);
end;

function CIEDE2000(L1, A1, B1, L2, A2, B2: Double): Double;
const
  DEG2RAD = Pi / 180.0;
  RAD2DEG = 180.0 / Pi;
var
  c1, c2, cbar_init, G: Double;
  a1p, a2p, c1p, c2p, cbar: Double;
  dLp, dCp, dhp, dHp: Double;
  h1p, h2p, hbar: Double;
  Lbar, T, dtheta, Rc: Double;
  Sl, Sc, Sh, Rt: Double;
  termL, termC, termH: Double;
begin
  // --- Step 1: G, a-prime, C-prime ---
  c1 := Sqrt(Sqr(A1) + Sqr(B1));
  c2 := Sqrt(Sqr(A2) + Sqr(B2));
  cbar_init := (c1 + c2) / 2.0;
  G := 0.5 * (1.0 - Sqrt(Power(cbar_init, 7.0)
       / (Power(cbar_init, 7.0) + Power(25.0, 7.0))));

  a1p := A1 * (1.0 + G * 0.5);
  a2p := A2 * (1.0 + G * 0.5);
  c1p := Sqrt(Sqr(a1p) + Sqr(B1));
  c2p := Sqrt(Sqr(a2p) + Sqr(B2));
  cbar := (c1p + c2p) / 2.0;

  // --- Step 2: Delta-L', Delta-C', Delta-h', Delta-H' ---
  dLp := L2 - L1;
  dCp := c2p - c1p;

  if c1p = 0.0 then
    h1p := 0.0
  else
    h1p := Arctan2(B1, a1p) * RAD2DEG;
  if h1p < 0.0 then
    h1p := h1p + 360.0;

  if c2p = 0.0 then
    h2p := 0.0
  else
    h2p := Arctan2(B2, a2p) * RAD2DEG;
  if h2p < 0.0 then
    h2p := h2p + 360.0;

  if (c1p * c2p) = 0.0 then
    dhp := 0.0
  else if Abs(h2p - h1p) <= 180.0 then
    dhp := h2p - h1p
  else if (h2p - h1p) > 180.0 then
    dhp := h2p - h1p - 360.0
  else
    dhp := h2p - h1p + 360.0;

  dHp := 2.0 * Sqrt(c1p * c2p) * Sin(dhp * DEG2RAD * 0.5);

  // --- Step 3: Weighting functions ---
  Lbar := (L1 + L2) / 2.0;

  if (c1p * c2p) = 0.0 then
    hbar := h1p + h2p
  else if Abs(h1p - h2p) <= 180.0 then
    hbar := (h1p + h2p) / 2.0
  else if (h1p + h2p) < 360.0 then
    hbar := (h1p + h2p + 360.0) / 2.0
  else
    hbar := (h1p + h2p - 360.0) / 2.0;

  T := 1.0
     - 0.17 * Cos((hbar - 30.0) * DEG2RAD)
     + 0.24 * Cos(2.0 * hbar * DEG2RAD)
     + 0.32 * Cos((3.0 * hbar + 6.0) * DEG2RAD)
     - 0.20 * Cos((4.0 * hbar - 63.0) * DEG2RAD);

  dtheta := 30.0 * Exp(-Sqr((hbar - 275.0) / 25.0));
  Rc := 2.0 * Sqrt(Power(cbar, 7.0)
       / (Power(cbar, 7.0) + Power(25.0, 7.0)));

  Sl := 1.0 + 0.015 * Sqr(Lbar - 50.0)
             / Sqrt(7.0 + Sqr(Lbar - 50.0));
  Sc := 1.0 + 0.045 * cbar;
  Sh := 1.0 + 0.015 * cbar * T;
  Rt := -Sin(2.0 * dtheta * DEG2RAD) * Rc;

  // --- Final Delta E 2000 (kL = kC = kH = 1) ---
  termL := dLp / Sl;
  termC := dCp / Sc;
  termH := dHp / Sh;

  Result := Sqrt(Sqr(termL) + Sqr(termC) + Sqr(termH) + Rt * termC * termH);
end;

function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
var
  L1, A1, B1v: Double;
  L2, A2, B2v: Double;
begin
  RGBtoLab(R1, G1, B1, L1, A1, B1v);
  RGBtoLab(R2, G2, B2, L2, A2, B2v);
  Result := CIEDE2000(L1, A1, B1v, L2, A2, B2v);
end;

end.
