const
  _25to7: Double = 6103515625.0;  // 25^7

function SRGBToLinear(const c: Byte): Double;
var
  x: Double;
begin
  x := c / 255.0;
  if x <= 0.04045 then
    Result := x / 12.92
  else
    Result := Power((x + 0.055) / 1.055, 2.4);
end;

procedure RGBToCIELAB(const R, G, B: Byte; out L, A, Bv: Double);
var
  r, g, bl: Double;
  X, Y, Z: Double;
  fx, fy, fz: Double;
const
  Xn = 0.95047;
  Yn = 1.0;
  Zn = 1.08883;
  D  = 6.0 / 29.0;
  E3 = D * D * D;
  KE = 3.0 * D * D;
  B4 = 4.0 / 29.0;
begin
  r  := SRGBToLinear(R);
  g  := SRGBToLinear(G);
  bl := SRGBToLinear(B);

  // sRGB linear -> XYZ (D65)
  X := 0.4124564 * r + 0.3575761 * g + 0.1804375 * bl;
  Y := 0.2126729 * r + 0.7151522 * g + 0.0721750 * bl;
  Z := 0.0193339 * r + 0.1191920 * g + 0.9503041 * bl;

  // Normalisiere auf D65-Wei%C3%9Fpunkt
  X := X / Xn;
  Y := Y / Yn;
  Z := Z / Zn;

  // XYZ -> CIELAB
  if X > E3 then fx := Power(X, 1.0 / 3.0) else fx := X / KE + B4;
  if Y > E3 then fy := Power(Y, 1.0 / 3.0) else fy := Y / KE + B4;
  if Z > E3 then fz := Power(Z, 1.0 / 3.0) else fz := Z / KE + B4;

  L  := 116.0 * fy - 16.0;
  A  := 500.0 * (fx - fy);
  Bv := 200.0 * (fy - fz);
end;

function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
var
  L1, A1, Bv1, L2, A2, Bv2: Double;
  C1, C2, Cbar, Cbar7, Gf: Double;
  A1p, A2p, C1p, C2p: Double;
  h1p, h2p, hbar: Double;
  dL, dC, dh, dH: Double;
  Lbar, Cbarp, Cbarp7, T: Double;
  dTheta, RC, SL, SC, SH, RT: Double;
  hbarRad, dThetaRad: Double;
begin
  RGBToCIELAB(R1, G1, B1, L1, A1, Bv1);
  RGBToCIELAB(R2, G2, B2, L2, A2, Bv2);

  // --- Schritt 1: C', h' berechnen ---
  C1   := Sqrt(A1 * A1 + Bv1 * Bv1);
  C2   := Sqrt(A2 * A2 + Bv2 * Bv2);
  Cbar := (C1 + C2) * 0.5;

  Cbar7 := Power(Cbar, 7.0);
  Gf    := 0.5 * (1.0 - Sqrt(Cbar7 / (Cbar7 + _25to7)));

  A1p   := A1 * (1.0 + Gf);
  A2p   := A2 * (1.0 + Gf);

  C1p   := Sqrt(A1p * A1p + Bv1 * Bv1);
  C2p   := Sqrt(A2p * A2p + Bv2 * Bv2);

  h1p   := ArcTan2(Bv1, A1p) * 180.0 / Pi;
  if h1p < 0.0 then h1p := h1p + 360.0;
  h2p   := ArcTan2(Bv2, A2p) * 180.0 / Pi;
  if h2p < 0.0 then h2p := h2p + 360.0;

  // --- Schritt 2: ΔL', ΔC', ΔH' ---
  dL := L2 - L1;
  dC := C2p - C1p;

  if C1p * C2p = 0.0 then
    dh := 0.0
  else if Abs(h1p - h2p) <= 180.0 then
    dh := h2p - h1p
  else if h1p + h2p < 360.0 then
    dh := h2p - h1p + 360.0
  else
    dh := h2p - h1p - 360.0;

  dH := 2.0 * Sqrt(C1p * C2p) * Sin(dh * Pi / 360.0);

  // --- Schritt 3: Gewichte und ΔE*00 ---
  Lbar  := (L1 + L2) * 0.5;
  Cbarp := (C1p + C2p) * 0.5;

  if C1p * C2p = 0.0 then
    hbar := h1p + h2p
  else if Abs(h1p - h2p) <= 180.0 then
    hbar := (h1p + h2p) * 0.5
  else if h1p + h2p < 360.0 then
    hbar := (h1p + h2p + 360.0) * 0.5
  else
    hbar := (h1p + h2p - 360.0) * 0.5;

  hbarRad := hbar * Pi / 180.0;

  T := 1.0
      - 0.17 * Cos(hbarRad - 30.0 * Pi / 180.0)
      + 0.24 * Cos(2.0 * hbarRad)
      + 0.32 * Cos(3.0 * hbarRad + 6.0 * Pi / 180.0)
      - 0.20 * Cos(4.0 * hbarRad - 63.0 * Pi / 180.0);

  dTheta := 30.0 * Exp(-((hbar - 275.0) / 25.0) * ((hbar - 275.0) / 25.0));

  Cbarp7 := Power(Cbarp, 7.0);
  RC     := 2.0 * Sqrt(Cbarp7 / (Cbarp7 + _25to7));

  SL := 1.0 + 0.015 * (Lbar - 50.0) * (Lbar - 50.0)
