  SC := 1.0 + 0.045 * Cbarp;
  SH := 1.0 + 0.015 * Cbarp * T;

  dThetaRad := dTheta * Pi / 180.0;
  RT := -Sin(2.0 * dThetaRad) * RC;

  // kL = kC = kH = 1
  Result := Sqrt(
    (dL / SL) * (dL / SL) +
    (dC / SC) * (dC / SC) +
    (dH / SH) * (dH / SH) +
    RT * (dC / SC) * (dH / SH)
  );
end;
