unit DeltaE2000;

interface

function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;

implementation

uses
  SysUtils, Math;

function SRGBtoLinear(const V: Byte): Double;
var
  v: Double;
begin
  v := V / 255.0;
  if v <= 0.04045 then
    Result := v / 12.92
  else
    Result := Power((v + 0.055) / 1.055, 2.4);
end;

procedure RGBtoXYZ(const R, G, B: Byte; out X, Y, Z: Double);
var
  r, g, b: Double;
begin
  r := SRGBtoLinear(R);
  g := SRGBtoLinear(G);
  b := SRGBtoLinear(B);
  X := 0.4124564 * r + 0.3575761 * g + 0.1804375 * b;
  Y := 0.2126729 * r + 0.7151522 * g + 0.0721750 * b;
  Z := 0.0193339 * r + 0.1191920 * g + 0.9503041 * b;
end;

procedure XYZtoLab(const X, Y, Z: Double; out L, A, B: Double);
const
  Xn = 95.047;
  Yn = 100.000;
  Zn = 108.883;
  EPS = (6.0 / 29.0) * (6.0 / 29.0) * (6.0 / 29.0);
  K3  = (16.0 / 116.0) * (16.0 / 116.0) * (16.0 / 116.0);
var
  xr, yr, zr: Double;
  fx, fy, fz: Double;
begin
  xr := X / Xn;
  yr := Y / Yn;
  zr := Z / Zn;

  if xr > EPS then fx := Power(xr, 1.0 / 3.0)
  else             fx := xr / (3.0 * K3) + 4.0 / 29.0;
  if yr > EPS then fy := Power(yr, 1.0 / 3.0)
  else             fy := yr / (3.0 * K3) + 4.0 / 29.0;
  if zr > EPS then fz := Power(zr, 1.0 / 3.0)
  else             fz := zr / (3.0 * K3) + 4.0 / 29.0;

  L := 116.0 * fy - 16.0;
  A := 500.0 * (fx - fy);
  B := 200.0 * (fy - fz);
end;

function HueFromAB(const A, B: Double): Double;
var
  h: Double;
begin
  if (Sqr(A) + Sqr(B)) < 1.0E-10 then
    Result := 0.0
  else begin
    h := RadToDeg(ArcTan2(B, A));
    if h < 0.0 then h := h + 360.0;
    Result := h;
  end;
end;

function AvgHue(const H1, H2: Double; const UseRatioTest: Boolean): Double;
var
  dH: Double;
begin
  dH := Abs(H1 - H2);
  if UseRatioTest then
    if dH / (360.0 - dH) <= 1.0 then
      Result := (H1 + H2) / 2.0
    else if H1 + H2 < 360.0 then
      Result := (H1 + H2 + 360.0) / 2.0
    else
      Result := (H1 + H2 - 360.0) / 2.0
  else begin
    if dH <= 180.0 then
      Result := (H1 + H2) / 2.0
    else if H1 + H2 < 360.0 then
      Result := (H1 + H2 + 360.0) / 2.0
    else
      Result := (H1 + H2 - 360.0) / 2.0;
  end;
end;

function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
var
  X1, Y1, Z1, X2, Y2, Z2: Double;
  L1, a1, b1, L2, a2, b2: Double;

  C1, C2, h1, h2: Double;
  Cbar, hbar: Double;
  G: Double;

  a1p, b1p, a2p, b2p: Double;
  C1p, C2p, C1pbar: Double;
  h1p, h2p, h1pbar: Double;

  dLp, dCp, dhp, dHp: Double;
  Lbarp: Double;
  T, dtheta, RC: Double;
  SL, SC, SH, RT: Double;
begin
  { --- sRGB → XYZ → CIELAB --- }
  RGBtoXYZ(R1, G1, B1, X1, Y1, Z1);
  RGBtoXYZ(R2, G2, B2, X2, Y2, Z2);
  XYZtoLab(X1, Y1, Z1, L1, a1, b1);
  XYZtoLab(X2, Y2, Z2, L2, a2, b2);

  { --- CIEDE2000 --- }

  { 1. C*ab und h_ab }
  C1 := Sqrt(Sqr(a1) + Sqr(b1));
  C2 := Sqrt(Sqr(a2) + Sqr(b2));
  h1 := HueFromAB(a1, b1);
  h2 := HueFromAB(a2, b2);

  { 2. Mittelwerte }
  Cbar := (C1 + C2) / 2.0;
  hbar := AvgHue(h1, h2, False);

  { 3. G-Faktor }
  G := 0.5 * (1.0 - Sqrt(Power(Cbar, 7) / (Power(Cbar, 7) + Power(25.0, 7))));

  { 4. a', b', C*', h' }
  a1p := (1.0 + G) * a1;
  b1p := b1;
  a2p := (1.0 + G) * a2;
  b2p := b2;

  C1p := Sqrt(Sqr(a1p) + Sqr(b1p));
  C2p := Sqrt(Sqr(a2p) + Sqr(b2p));
  h1p := HueFromAB(a1p, b1p);
  h2p := HueFromAB(a2p, b2p);

  { 5. Differenzen }
  dLp := L2 - L1;
  dCp := C2p - C1p;

  if Abs(h2p - h1p) <= 180.0 then
    dhp := h2p - h1p
  else if h2p - h1p > 180.0 then
    dhp := h2p - h1p - 360.0
  else
    dhp := h2p - h1p + 360.0;

  dHp := 2.0 * Sqrt(C1p * C2p) * Sin(DegToRad(dhp / 2.0));

  { 6. Mittelwerte im primierten Raum }
  Lbarp  := (L1 + L2) / 2.0;
  C1pbar := (C1p + C2p) / 2.0;
  h1pbar := AvgHue(h1p, h2p, True);

  { 7. T }
  T := 1.0
    - 0.17 * Cos(DegToRad(h1pbar - 30.0))
    + 0.24 * Cos(DegToRad(2.0 * h1pbar))
    + 0.32 * Cos(DegToRad(3.0 * h1pbar + 6.0))
    - 0.20 * Cos(DegToRad(4.0 * h1pbar - 63.0));

  { 8. Gewichtungsfunktionen (kL = kC = kH = 1) }
  dtheta := 30.0 * Exp(-Sqr((h1pbar - 275.0) / 25.0));
  RC     := 2.0 * Sqrt(Power(C1pbar, 7) / (Power(C1pbar, 7) + Power(25.0, 7)));
