var
  h: Double;
begin
  if (Sqr(A) + Sqr(B)) < 1.0E-10 then
    Result := 0.0
  else begin
    h := RadToDeg(ArcTan2(B, A));
    if h < 0.0 then h := h + 360.0;
    Result := h;
  end;
end;

