unit DeltaE2000Unit;

interface

uses
  SysUtils, Math;

function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;

implementation

const
  D65_Xn = 0.95047;
  D65_Yn = 1.00000;
  D65_Zn = 1.08883;
  DEG_TO_RAD = Pi / 180.0;
  Epsilon = 216.0 / 24389.0;   // (6/29)^3
  Kappa   = 24389.0 / 27.0;    // (29/3)^3

function sRGBToLinear(C: Double): Double;
begin
  if C <= 0.04045 then
    Result := C / 12.92
  else
    Result := Power((C + 0.055) / 1.055, 2.4);
end;

procedure RGBToLab(R, G, B: Byte; out L, a, b: Double);
var
  rLin, gLin, bLin: Double;
  X, Y, Z: Double;
  fx, fy, fz: Double;

  function F(t: Double): Double;
  begin
    if t > Epsilon then
      Result := Power(t, 1.0 / 3.0)
    else
      Result := (Kappa * t + 16.0) / 116.0;
  end;

begin
  rLin := sRGBToLinear(R / 255.0);
  gLin := sRGBToLinear(G / 255.0);
  bLin := sRGBToLinear(B / 255.0);

  X := 0.4124564 * rLin + 0.3575761 * gLin + 0.1804375 * bLin;
  Y := 0.2126729 * rLin + 0.7151522 * gLin + 0.0721750 * bLin;
  Z := 0.0193339 * rLin + 0.1191920 * gLin + 0.9503041 * bLin;

  fx := F(X / D65_Xn);
  fy := F(Y / D65_Yn);
  fz := F(Z / D65_Zn);

  L := 116.0 * fy - 16.0;
  a := 500.0 * (fx - fy);
  b := 200.0 * (fy - fz);
end;

function NormalizeHue(h: Double): Double;
begin
  Result := h - Floor(h / 360.0) * 360.0;
  if Result < 0 then
    Result := Result + 360.0;
end;

function DeltaE2000(R1, G1, B1, R2, G2, B2: Byte): Double;
var
  L1, a1, b1, L2, a2, b2: Double;
  C1, C2, Cbar: Double;
  G: Double;
  a1p, a2p: Double;
  C1p, C2p: Double;
  h1p, h2p: Double;
  Lbar, Cbarp, hbarp: Double;
  dL, dC, dh: Double;
  T, RT: Double;
  SL, SC, SH: Double;
  dTheta, RC: Double;
  deltaH2p: Double;
  hDiff: Double;
begin
  RGBToLab(R1, G1, B1, L1, a1, b1);
  RGBToLab(R2, G2, B2, L2, a2, b2);

  // --- Step 1: Mean chroma ---
  C1 := Sqrt(a1 * a1 + b1 * b1);
  C2 := Sqrt(a2 * a2 + b2 * b2);
  Cbar := (C1 + C2) / 2.0;

  // --- Step 2: Factor G ---
  G := 0.5 * (1.0 - Sqrt(Power(Cbar, 7.0) / (Power(Cbar, 7.0) + 6103515625.0))); // 25^7

  // --- Step 3: a' adjusted ---
  a1p := (1.0 + G) * a1;
  a2p := (1.0 + G) * a2;

  // --- Step 4: C' ---
  C1p := Sqrt(a1p * a1p + b1 * b1);
  C2p := Sqrt(a2p * a2p + b2 * b2);

  // --- Step 5: h' ---
  if (a1p = 0) and (b1 = 0) then
    h1p := 0.0
  else
    h1p := NormalizeHue(ArcTan2(b1, a1p) / DEG_TO_RAD);

  if (a2p = 0) and (b2 = 0) then
    h2p := 0.0
  else
    h2p := NormalizeHue(ArcTan2(b2, a2p) / DEG_TO_RAD);

  // --- Step 6: Weighted means ---
  Lbar  := (L1 + L2) / 2.0;
  Cbarp := (C1p + C2p) / 2.0;

  hDiff := Abs(h2p - h1p);
  if C1p * C2p = 0 then
    hbarp := h1p + h2p   // one of them is 0, doesn't matter for RT
  else if hDiff <= 180.0 then
    hbarp := (h1p + h2p) / 2.0
  else if h1p + h2p < 360.0 then
    hbarp := (h1p + h2p + 360.0) / 2.0
  else
    hbarp := (h1p + h2p - 360.0) / 2.0;

  // --- Step 7: T ---
  T := 1.0
     - 0.17 * Cos((hbarp - 30.0) * DEG_TO_RAD)
     + 0.24 * Cos(2.0 * hbarp * DEG_TO_RAD)
     + 0.32 * Cos((3.0 * hbarp + 6.0) * DEG_TO_RAD)
     - 0.20 * Cos((4.0 * hbarp - 63.0) * DEG_TO_RAD);

  // --- Step 8: Differences ---
  dL := L2 - L1;
  dC := C2p - C1p;

  if C1p * C2p = 0 then
    deltaH2p := 0.0
  else begin
    hDiff := h2p - h1p;
    if hDiff > 180.0 then
      hDiff := hDiff - 360.0
    else if hDiff < -180.0 then
      hDiff := hDiff + 360.0;
    dh := hDiff;
    deltaH2p := 2.0 * Sqrt(C1p * C2p) * Sin(dh * DEG_TO_RAD / 2.0);
  end;

  // --- Step 9: SL, SC, SH ---
  SL := 1.0 + (0.015 * Sqr(Lbar - 50.0)) / Sqrt(20.0 + Sqr(Lbar - 50.0));
  SC := 1.0 + 0.045 * Cbarp;
  SH := 1.0 + 0.015 * Cbarp * T;

  // --- Step 10: RT (rotation term) ---
  dTheta := 30.0 * Exp(-Sqr((hbarp - 275.0) / 25.0));
  RC := 2.0 * Sqrt(Power(Cbarp, 7.0) / (Power(Cbarp, 7.0) + 6103515625.0));
  RT := -Sin(2.0 * dTheta * DEG_TO_RAD) * RC;

  // --- Final Delta E 2000 (kL=kC=kH=1) ---
  Result := Sqrt(
    Sqr(dL / SL) +
    Sqr(dC / SC) +
    Sqr(deltaH2p / SH) +
    RT * (dC / SC) * (deltaH2p / SH)
  );
end;

